wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::kb_read;

struct Node;

const MAX_QUESTION_CHARS: usize = 512;
const NO_KNOWLEDGE: &str = "no matching knowledge";

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let intent = query.query.intent;
        let question: String = query
            .query
            .question
            .chars()
            .take(MAX_QUESTION_CHARS)
            .collect();

        let mut knowledge = kb_read::lookup(&question);
        if knowledge.is_empty() {
            knowledge.push(NO_KNOWLEDGE.to_string());
        }

        ConversationContext {
            intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
